import type { ReactNode } from 'react'
import type { Review } from '../../types'
import { Avatar } from '@/components/common/Avatar'
import { Star } from 'lucide-react'

interface ReviewCardProps {
  review: Review
}

/**
 * ReviewCard — a single guest review in the reviews grid.
 */
export function ReviewCard({ review }: ReviewCardProps): ReactNode {
  return (
    <article className="review">
      <Avatar initial={review.initial} />
      <div>
        <b>{review.name}</b>
        <small>Guest · {review.when}</small>
        <p>
          <Star size={12} fill="currentColor" aria-hidden="true" />
          {review.score} · {review.text}
        </p>
        <a href="#" aria-label={`Show more from ${review.name}`}>Show more</a>
      </div>
    </article>
  )
}
