'use client'

import type { ReactNode } from 'react'
import type { Review } from '../../types'
import { ReviewCard } from './ReviewCard'
import { RatingBars } from './RatingBars'
import { REVIEW_TAGS } from '../../constants/mock-data'

interface ReviewsSectionProps {
  reviews: Review[]
  totalCount: number
  onShowAll: () => void
}

/**
 * ReviewsSection — the full reviews section with rating summary, tags, and review grid.
 */
export function ReviewsSection({ reviews, totalCount, onShowAll }: ReviewsSectionProps): ReactNode {
  return (
    <section id="reviews" className="content-section" aria-labelledby="reviews-heading">
      {/* Rating mark */}
      <div className="rating-mark" aria-label="Overall rating">
        <span aria-hidden="true">✦</span>
        <strong>4.95</strong>
        <small>Guest favourite</small>
      </div>

      {/* Section title row */}
      <div className="section-title-row">
        <div>
          <h2 id="reviews-heading">Guest favourite</h2>
          <p>One of the most loved homes on Airbnb, according to guests</p>
        </div>
        <a href="#" aria-label="Learn how reviews work">How reviews work</a>
      </div>

      {/* Rating bars and category scores */}
      <RatingBars />

      {/* Review tags */}
      <div className="tags" role="list" aria-label="Guest review highlights">
        {REVIEW_TAGS.map((tag) => (
          <span key={tag} role="listitem">{tag}</span>
        ))}
      </div>

      {/* Review cards */}
      <div className="review-grid">
        {reviews.map((review) => (
          <ReviewCard key={review.name} review={review} />
        ))}
      </div>

      <button className="outline-btn" onClick={onShowAll}>
        Show all {totalCount} reviews
      </button>
    </section>
  )
}
