'use client'

import Image from 'next/image'
import { Camera } from 'lucide-react'
import type { ReactNode } from 'react'
import type { Photo } from '../../types'
import { PhotoThumbnail } from './PhotoThumbnail'

interface PhotoGridProps {
  photos: Photo[]
  onPhotoClick: (index: number) => void
}

/**
 * PhotoGrid — the 5-photo hero grid at the top of the listing.
 * Hero photo on the left, 4 smaller photos in a 2×2 grid on the right.
 */
export function PhotoGrid({ photos, onPhotoClick }: PhotoGridProps): ReactNode {
  const [hero, ...smallPhotos] = photos.slice(0, 5)

  return (
    <section className="photo-grid" id="photos" aria-label="Property photos">
      {/* Hero photo */}
      <button
        className="hero-photo photo-button"
        onClick={() => onPhotoClick(0)}
        aria-label={`View photo: ${hero.alt}`}
      >
        <Image
          src={hero.src}
          alt={hero.alt}
          fill
          priority
          sizes="50vw"
        />
      </button>

      {/* 4 smaller photos */}
      <div className="small-photos">
        {smallPhotos.map((photo, i) => (
          <PhotoThumbnail
            key={photo.src}
            photo={photo}
            index={i + 1}
            onClick={onPhotoClick}
            showAllPhotos={i === 3}
          />
        ))}
      </div>
    </section>
  )
}
