import Image from 'next/image'
import { Camera } from 'lucide-react'
import type { ReactNode } from 'react'
import type { Photo } from '../../types'

interface PhotoThumbnailProps {
  photo: Photo
  index: number
  onClick: (index: number) => void
  showAllPhotos?: boolean
}

/**
 * PhotoThumbnail — a single photo button in the photo grid.
 * Optionally shows a "Show all photos" overlay on the last thumbnail.
 */
export function PhotoThumbnail({
  photo,
  index,
  onClick,
  showAllPhotos = false,
}: PhotoThumbnailProps): ReactNode {
  return (
    <button
      className="photo-button"
      onClick={() => onClick(index)}
      aria-label={showAllPhotos ? 'Show all photos' : `View photo: ${photo.alt}`}
    >
      <Image src={photo.src} alt={photo.alt} fill sizes="25vw" />
      {showAllPhotos && (
        <span className="show-all" aria-hidden="true">
          <Camera size={16} />
          Show all photos
        </span>
      )}
    </button>
  )
}
